cat > /app/output/index.html <<'HTML'
<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Fresh Pantry — Discover Everyday Deliciousness</title>
  <meta name="description" content="Fresh Pantry is your neighborhood grocery store for unique, high-quality food products at great prices." />
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Nunito:wght@600;700;800&family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
  <style>
    :root {
      --cream: #fffdf7;
      --cream-2: #fff8ec;
      --green: #3a7d44;
      --green-2: #5a9b64;
      --green-3: #eaf6ec;
      --yellow: #f6c64a;
      --terracotta: #d97a5e;
      --ink: #253029;
      --muted: #5f6f64;
      --white: #ffffff;
      --shadow: 0 8px 24px rgba(37, 48, 41, 0.09);
      --radius-lg: 22px;
      --radius-md: 16px;
      --radius-sm: 12px;
    }

    * { box-sizing: border-box; }

    html { scroll-behavior: smooth; }

    body {
      margin: 0;
      font-family: "Inter", system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
      background: linear-gradient(180deg, var(--cream) 0%, #fffcf3 45%, var(--white) 100%);
      color: var(--ink);
      line-height: 1.55;
    }

    img { max-width: 100%; display: block; }

    a { color: inherit; text-decoration: none; }

    .container {
      width: min(1120px, calc(100% - 2rem));
      margin-inline: auto;
    }

    h1, h2, h3 {
      margin: 0;
      font-family: "Nunito", "Inter", sans-serif;
      letter-spacing: -0.02em;
      color: #1f3a28;
    }

    h2 { font-size: clamp(1.6rem, 2.3vw, 2.25rem); }

    .section { padding: 4rem 0; }

    .section-top {
      display: flex;
      justify-content: space-between;
      align-items: flex-end;
      gap: 1rem;
      margin-bottom: 1.5rem;
    }

    .eyebrow {
      display: inline-flex;
      background: #eff8f0;
      border: 1px solid #dbefdd;
      color: var(--green);
      border-radius: 999px;
      padding: 0.35rem 0.75rem;
      font-size: 0.8rem;
      font-weight: 700;
      margin-bottom: 0.8rem;
    }

    .muted { color: var(--muted); }

    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 0.5rem;
      border: 0;
      border-radius: 999px;
      padding: 0.78rem 1.2rem;
      font-weight: 700;
      font-size: 0.95rem;
      cursor: pointer;
      transition: transform 220ms ease, box-shadow 220ms ease, background-color 220ms ease;
      min-height: 44px;
      min-width: 44px;
    }

    .btn-primary {
      background: var(--green);
      color: var(--white);
      box-shadow: 0 6px 16px rgba(58, 125, 68, 0.28);
    }

    .btn-primary:hover { background: #30673a; transform: translateY(-1px); }
    .btn-primary:focus-visible,
    .icon-btn:focus-visible,
    .nav-link:focus-visible,
    input:focus-visible {
      outline: 3px solid rgba(246, 198, 74, 0.55);
      outline-offset: 2px;
    }

    .btn-warm {
      background: var(--terracotta);
      color: var(--white);
      box-shadow: 0 6px 16px rgba(217, 122, 94, 0.26);
    }

    .btn-warm:hover { background: #c96a4f; transform: translateY(-1px); }

    header {
      position: sticky;
      top: 0;
      z-index: 40;
      backdrop-filter: blur(10px);
      background: rgba(255, 253, 247, 0.86);
      border-bottom: 1px solid rgba(58, 125, 68, 0.12);
    }

    .topbar {
      display: flex;
      align-items: center;
      justify-content: space-between;
      min-height: 72px;
      gap: 1rem;
    }

    .brand {
      font-family: "Nunito", sans-serif;
      font-size: 1.35rem;
      font-weight: 800;
      color: #244f2e;
      display: inline-flex;
      align-items: center;
      gap: 0.45rem;
    }

    .brand-mark {
      width: 1.7rem;
      height: 1.7rem;
      display: inline-grid;
      place-items: center;
      border-radius: 0.55rem;
      background: linear-gradient(145deg, #74ba7f, #3d8748);
      color: #fff;
      font-size: 1rem;
      font-weight: 900;
    }

    nav {
      display: flex;
      gap: 0.5rem;
      flex-wrap: wrap;
      justify-content: center;
    }

    .nav-link {
      font-weight: 600;
      color: #2f4337;
      padding: 0.55rem 0.85rem;
      border-radius: 999px;
      transition: background-color 200ms ease, color 200ms ease;
      min-height: 44px;
      display: inline-flex;
      align-items: center;
    }

    .nav-link:hover { background: #edf7ee; color: #275432; }

    .hero {
      padding: 4.25rem 0 3.2rem;
    }

    .hero-wrap {
      display: grid;
      grid-template-columns: 1.05fr 0.95fr;
      gap: 2rem;
      align-items: center;
    }

    .hero h1 {
      font-size: clamp(2rem, 5vw, 3.45rem);
      line-height: 1.08;
      margin-bottom: 1rem;
    }

    .hero p {
      color: #4a5f52;
      max-width: 52ch;
      margin-bottom: 1.4rem;
      font-size: 1.05rem;
    }

    .hero-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.7rem;
    }

    .hero-card {
      background: var(--white);
      border-radius: var(--radius-lg);
      padding: 1rem;
      box-shadow: var(--shadow);
      border: 1px solid #e8f1e9;
    }

    .hero-card img {
      border-radius: 16px;
      aspect-ratio: 4/3;
      object-fit: cover;
    }

    .stats-banner {
      margin-top: 2.25rem;
      background: linear-gradient(120deg, #eff8f0, #fff5de);
      border: 1px solid #e2efdf;
      border-radius: 20px;
      padding: 1.2rem;
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 0.8rem;
    }

    .stat {
      background: rgba(255, 255, 255, 0.72);
      border-radius: 14px;
      padding: 0.9rem;
      text-align: center;
      border: 1px solid #e9f1e7;
    }

    .stat strong {
      display: block;
      font-family: "Nunito", sans-serif;
      font-size: clamp(1.2rem, 2.4vw, 1.7rem);
      color: #275c32;
    }

    .carousel-shell {
      position: relative;
    }

    .carousel-track {
      display: grid;
      grid-auto-flow: column;
      grid-auto-columns: calc((100% - 2rem) / 3);
      gap: 1rem;
      overflow-x: auto;
      scroll-behavior: smooth;
      scrollbar-width: none;
      padding-bottom: 0.3rem;
    }

    .carousel-track::-webkit-scrollbar { display: none; }

    .product-card {
      background: var(--white);
      border-radius: var(--radius-md);
      border: 1px solid #e9efe8;
      box-shadow: var(--shadow);
      overflow: hidden;
      min-height: 100%;
    }

    .product-card img {
      aspect-ratio: 4/3;
      object-fit: cover;
      width: 100%;
    }

    .product-body { padding: 0.95rem; }

    .product-name {
      font-weight: 700;
      margin-bottom: 0.35rem;
      color: #294a35;
    }

    .price {
      font-weight: 800;
      color: #1f6b3a;
      font-family: "Nunito", sans-serif;
      font-size: 1.05rem;
    }

    .carousel-controls {
      display: flex;
      gap: 0.5rem;
      margin-top: 1rem;
      justify-content: flex-end;
    }

    .icon-btn {
      border: 1px solid #dbeadf;
      background: #fff;
      color: #2c4f37;
      width: 44px;
      height: 44px;
      border-radius: 999px;
      cursor: pointer;
      font-size: 1.2rem;
      transition: transform 180ms ease, background-color 180ms ease;
    }

    .icon-btn:hover { transform: translateY(-1px); background: #f2f9f3; }

    .seasonal {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 1rem;
    }

    .season-card {
      position: relative;
      overflow: hidden;
      border-radius: var(--radius-md);
      border: 1px solid #e8efe8;
      box-shadow: var(--shadow);
      min-height: 220px;
    }

    .season-card img {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .season-overlay {
      position: absolute;
      inset: 0;
      background: linear-gradient(to top, rgba(24, 32, 26, 0.64), rgba(0, 0, 0, 0.06));
      color: #fff;
      padding: 1.1rem;
      display: flex;
      flex-direction: column;
      justify-content: flex-end;
    }

    .categories-grid {
      display: grid;
      grid-template-columns: repeat(5, 1fr);
      gap: 0.9rem;
    }

    .cat-card {
      position: relative;
      min-height: 200px;
      border-radius: 18px;
      overflow: hidden;
      border: 1px solid #e8efe8;
      box-shadow: var(--shadow);
      transition: transform 220ms ease;
      transform-origin: center;
    }

    .cat-card img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      transition: transform 320ms ease;
    }

    .cat-overlay {
      position: absolute;
      inset: 0;
      background: linear-gradient(to top, rgba(24, 36, 28, 0.73), rgba(40, 63, 46, 0.14));
      display: grid;
      place-items: end start;
      padding: 0.9rem;
      color: #fff;
      font-weight: 700;
      font-family: "Nunito", sans-serif;
      letter-spacing: 0.01em;
      opacity: 0.9;
      transition: opacity 220ms ease;
    }

    .cat-card:hover,
    .cat-card:focus-within {
      transform: scale(1.03);
    }

    .cat-card:hover img,
    .cat-card:focus-within img {
      transform: scale(1.05);
    }

    .cat-card:hover .cat-overlay,
    .cat-card:focus-within .cat-overlay {
      opacity: 1;
    }

    .panel {
      background: var(--white);
      border: 1px solid #e6efe6;
      border-radius: 20px;
      box-shadow: var(--shadow);
      padding: 1.2rem;
    }

    .store-form,
    .news-form {
      display: flex;
      gap: 0.7rem;
      flex-wrap: wrap;
      margin-top: 1rem;
    }

    input {
      flex: 1 1 220px;
      min-height: 46px;
      border-radius: 12px;
      border: 1px solid #cadacb;
      padding: 0.72rem 0.9rem;
      font: inherit;
      background: #fffefb;
    }

    .results,
    .confirm {
      margin-top: 1rem;
      display: none;
    }

    .results.show,
    .confirm.show { display: block; }

    table {
      width: 100%;
      border-collapse: collapse;
      margin-top: 0.5rem;
      overflow: hidden;
      border-radius: 12px;
      border: 1px solid #dce9dd;
    }

    th, td {
      text-align: left;
      padding: 0.75rem;
      font-size: 0.95rem;
      border-bottom: 1px solid #ebf2eb;
    }

    th {
      background: #f2f9f3;
      color: #32553d;
      font-weight: 700;
    }

    footer {
      background: linear-gradient(160deg, #1f3d2a 0%, #275436 100%);
      color: #eaf4ed;
      margin-top: 4rem;
      padding: 3rem 0 2rem;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: 1.4fr repeat(4, 1fr);
      gap: 1rem;
    }

    .footer-col h3 {
      color: #f4fff6;
      margin-bottom: 0.6rem;
      font-size: 1.05rem;
    }

    .footer-col a {
      display: block;
      padding: 0.2rem 0;
      color: #d7e6dc;
      font-size: 0.95rem;
    }

    .footer-col a:hover { color: #fff8dc; }

    .footer-tagline {
      margin-top: 1.2rem;
      border-top: 1px solid rgba(234, 244, 237, 0.2);
      padding-top: 1rem;
      color: #d8e9de;
      font-size: 0.9rem;
    }

    @media (max-width: 980px) {
      .hero-wrap,
      .seasonal,
      .footer-grid {
        grid-template-columns: 1fr;
      }

      .stats-banner { grid-template-columns: repeat(2, 1fr); }
      .carousel-track { grid-auto-columns: calc((100% - 1rem) / 2); }
      .categories-grid { grid-template-columns: repeat(3, 1fr); }
    }

    @media (max-width: 680px) {
      .section { padding: 3rem 0; }
      .topbar { flex-direction: column; align-items: stretch; padding: 0.8rem 0; }
      nav { justify-content: flex-start; }
      .hero { padding-top: 2.7rem; }
      .stats-banner { grid-template-columns: 1fr; }
      .carousel-track { grid-auto-columns: 90%; }
      .categories-grid { grid-template-columns: 1fr 1fr; }
      .store-form .btn,
      .news-form .btn { width: 100%; }
      th, td { font-size: 0.88rem; }
    }

    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
      }
    }
  </style>
</head>
<body>
  <header>
    <div class="container topbar">
      <a class="brand" href="#top" aria-label="Fresh Pantry home">
        <span class="brand-mark">F</span>
        Fresh Pantry
      </a>
      <nav aria-label="Primary navigation">
        <a class="nav-link" href="#featured-products">Products</a>
        <a class="nav-link" href="#store-locator">Our Stores</a>
        <a class="nav-link" href="#seasonal-picks">Recipes</a>
        <a class="nav-link" href="#footer-about">About Us</a>
      </nav>
    </div>
  </header>

  <main id="top">
    <section class="hero">
      <div class="container hero-wrap">
        <div>
          <span class="eyebrow">Neighborhood Grocery Magic</span>
          <h1>Discover Everyday<br>Deliciousness</h1>
          <p>
            Fresh Pantry is your neighborhood grocery destination for unique, high-quality food products at great prices.
            Browse exciting staples, seasonal treasures, and new weekly finds — all selected to make healthy shopping feel fun and easy.
          </p>
          <div class="hero-actions">
            <a class="btn btn-primary" href="#featured-products">Shop Featured Finds</a>
            <a class="btn btn-warm" href="#store-locator">Find a Store Near You</a>
          </div>
        </div>
        <article class="hero-card" aria-label="Fresh food lifestyle image">
          <img src="https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&w=1200&q=80" alt="Colorful grocery produce arranged in a bright market setting" loading="lazy">
        </article>
      </div>

      <div class="container">
        <div class="stats-banner" aria-label="Brand highlights">
          <div class="stat"><strong>500+</strong><span>Stores Nationwide</span></div>
          <div class="stat"><strong>4,000+</strong><span>Unique Products</span></div>
          <div class="stat"><strong>80%</strong><span>Private Label Items</span></div>
          <div class="stat"><strong>New Weekly</strong><span>Fresh Finds Added</span></div>
        </div>
      </div>
    </section>

    <section id="featured-products" class="section">
      <div class="container">
        <div class="section-top">
          <div>
            <span class="eyebrow">Featured Products</span>
            <h2>Today’s Pantry Stars</h2>
            <p class="muted">Swipe through handpicked favorites with unbeatable everyday prices.</p>
          </div>
        </div>

        <div class="carousel-shell">
          <div class="carousel-track" id="productTrack" aria-label="Featured products carousel">
            <article class="product-card">
              <img src="https://images.unsplash.com/photo-1515003197210-e0cd71810b5f?auto=format&fit=crop&w=900&q=80" alt="Organic Maple Granola in a bowl" loading="lazy">
              <div class="product-body">
                <div class="product-name">Organic Maple Granola</div>
                <div class="price">$4.99</div>
              </div>
            </article>
            <article class="product-card">
              <img src="https://images.unsplash.com/photo-1512621776951-a57141f2eefd?auto=format&fit=crop&w=900&q=80" alt="Everything But The Bagel seasoning alongside fresh ingredients" loading="lazy">
              <div class="product-body">
                <div class="product-name">Everything But The Bagel Seasoning</div>
                <div class="price">$2.49</div>
              </div>
            </article>
            <article class="product-card">
              <img src="https://images.unsplash.com/photo-1606312619070-d48b4c652a52?auto=format&fit=crop&w=900&q=80" alt="Dark chocolate peanut butter cups on wooden board" loading="lazy">
              <div class="product-body">
                <div class="product-name">Dark Chocolate Peanut Butter Cups</div>
                <div class="price">$3.99</div>
              </div>
            </article>
            <article class="product-card">
              <img src="https://images.unsplash.com/photo-1611273426858-450e7f08d386?auto=format&fit=crop&w=900&q=80" alt="Cauliflower gnocchi in a skillet with herbs" loading="lazy">
              <div class="product-body">
                <div class="product-name">Cauliflower Gnocchi</div>
                <div class="price">$2.99</div>
              </div>
            </article>
            <article class="product-card">
              <img src="https://images.unsplash.com/photo-1604908177522-4028f2f544d8?auto=format&fit=crop&w=900&q=80" alt="Mandarin orange chicken plated with rice" loading="lazy">
              <div class="product-body">
                <div class="product-name">Mandarin Orange Chicken</div>
                <div class="price">$5.49</div>
              </div>
            </article>
          </div>
          <div class="carousel-controls">
            <button class="icon-btn" id="prevBtn" aria-label="Previous featured products">←</button>
            <button class="icon-btn" id="nextBtn" aria-label="Next featured products">→</button>
          </div>
        </div>
      </div>
    </section>

    <section id="seasonal-picks" class="section">
      <div class="container">
        <span class="eyebrow">Seasonal Picks</span>
        <div class="section-top">
          <h2>Fresh Discoveries for This Week</h2>
        </div>
        <div class="seasonal">
          <article class="season-card">
            <img src="https://images.unsplash.com/photo-1478145046317-39f10e56b5e9?auto=format&fit=crop&w=1200&q=80" alt="Colorful citrus fruits and herbs styled on a table" loading="lazy">
            <div class="season-overlay">
              <h3>Citrus Brights</h3>
              <p>Sunny flavors to wake up breakfast and snack time.</p>
            </div>
          </article>
          <article class="season-card">
            <img src="https://images.unsplash.com/photo-1488459716781-31db52582fe9?auto=format&fit=crop&w=1200&q=80" alt="Warm soup ingredients and pantry staples in cozy kitchen" loading="lazy">
            <div class="season-overlay">
              <h3>Cozy Pantry Staples</h3>
              <p>Comforting essentials perfect for quick wholesome dinners.</p>
            </div>
          </article>
        </div>
      </div>
    </section>

    <section id="categories" class="section">
      <div class="container">
        <span class="eyebrow">Shop by Category</span>
        <div class="section-top">
          <h2>Explore the Aisles</h2>
        </div>
        <div class="categories-grid">
          <a href="#" class="cat-card" aria-label="Snacks and sweets category">
            <img src="https://images.unsplash.com/photo-1599490659213-e2b9527bd087?auto=format&fit=crop&w=900&q=80" alt="Assorted healthy snack treats" loading="lazy">
            <div class="cat-overlay">Snacks &amp; Sweets</div>
          </a>
          <a href="#" class="cat-card" aria-label="Fresh produce category">
            <img src="https://images.unsplash.com/photo-1540420773420-3366772f4999?auto=format&fit=crop&w=900&q=80" alt="Fresh produce including tomatoes and leafy greens" loading="lazy">
            <div class="cat-overlay">Fresh Produce</div>
          </a>
          <a href="#" class="cat-card" aria-label="Frozen favorites category">
            <img src="https://images.unsplash.com/photo-1511690743698-d9d85f2fbf38?auto=format&fit=crop&w=900&q=80" alt="Frozen food favorites styled on a countertop" loading="lazy">
            <div class="cat-overlay">Frozen Favorites</div>
          </a>
          <a href="#" class="cat-card" aria-label="Beverages category">
            <img src="https://images.unsplash.com/photo-1499638673689-79a0b5115d87?auto=format&fit=crop&w=900&q=80" alt="Fresh beverages and juices" loading="lazy">
            <div class="cat-overlay">Beverages</div>
          </a>
          <a href="#" class="cat-card" aria-label="Dairy and cheese category">
            <img src="https://images.unsplash.com/photo-1488477181946-6428a0291777?auto=format&fit=crop&w=900&q=80" alt="Dairy and artisan cheese assortment" loading="lazy">
            <div class="cat-overlay">Dairy &amp; Cheese</div>
          </a>
        </div>
      </div>
    </section>

    <section id="store-locator" class="section">
      <div class="container panel">
        <span class="eyebrow">Store Locator</span>
        <h2>Find a Fresh Pantry Near You</h2>
        <p class="muted">Enter your zip code to discover the nearest store, hours, and directions.</p>

        <form class="store-form" id="storeForm" novalidate>
          <input id="zipInput" type="text" inputmode="numeric" autocomplete="postal-code" placeholder="Enter your zip code" aria-label="Zip code">
          <button class="btn btn-primary" type="submit">Search</button>
        </form>

        <div class="results" id="storeResults" aria-live="polite">
          <table>
            <thead>
              <tr>
                <th>Store Name</th>
                <th>Address</th>
                <th>Hours</th>
                <th>Distance</th>
              </tr>
            </thead>
            <tbody>
              <tr>
                <td>Fresh Pantry — Lincoln Park</td>
                <td>2140 N. Halsted St, Chicago, IL 60614</td>
                <td>8am – 9pm Daily</td>
                <td>0.8 mi</td>
              </tr>
              <tr>
                <td>Fresh Pantry — Wicker Park</td>
                <td>1840 W. North Ave, Chicago, IL 60622</td>
                <td>8am – 9pm Daily</td>
                <td>1.4 mi</td>
              </tr>
              <tr>
                <td>Fresh Pantry — Lakeview</td>
                <td>3745 N. Lincoln Ave, Chicago, IL 60613</td>
                <td>8am – 9pm Daily</td>
                <td>2.1 mi</td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>
    </section>

    <section id="newsletter" class="section">
      <div class="container panel" style="background: linear-gradient(145deg, #fffaf0, #fffef9);">
