  <script>
    const productTrack = document.getElementById('productTrack');
    const nextBtn = document.getElementById('nextBtn');
    const prevBtn = document.getElementById('prevBtn');

    function getScrollAmount() {
      const card = productTrack.querySelector('.product-card');
      if (!card) return 320;
      const styles = getComputedStyle(productTrack);
      const gap = parseFloat(styles.columnGap || styles.gap || 16);
      return card.offsetWidth + gap;
    }

    nextBtn.addEventListener('click', () => {
      productTrack.scrollBy({ left: getScrollAmount(), behavior: 'smooth' });
    });

    prevBtn.addEventListener('click', () => {
      productTrack.scrollBy({ left: -getScrollAmount(), behavior: 'smooth' });
    });

    const storeForm = document.getElementById('storeForm');
    const zipInput = document.getElementById('zipInput');
    const storeResults = document.getElementById('storeResults');

    storeForm.addEventListener('submit', (event) => {
      event.preventDefault();
      const zip = zipInput.value.trim();
      if (zip.length < 3) {
        zipInput.setCustomValidity('Please enter a valid zip code.');
        zipInput.reportValidity();
        return;
      }
      zipInput.setCustomValidity('');
      storeResults.classList.add('show');
    });

    const newsForm = document.getElementById('newsForm');
    const emailInput = document.getElementById('emailInput');
    const newsConfirm = document.getElementById('newsConfirm');

    newsForm.addEventListener('submit', (event) => {
      event.preventDefault();
      if (!emailInput.value.trim() || !emailInput.checkValidity()) {
        emailInput.reportValidity();
        return;
      }
      newsConfirm.classList.add('show');
      newsForm.reset();
    });
  </script>
